package org.apache.commons.io.file.attribute;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.Instant;
import java.util.stream.Stream;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

public class FileTimesTest_testMaxJavaTimeParam {

    private static final long ONE_MILLISECOND_IN_NTFS_UNITS = FileTimes.HUNDRED_NANOS_PER_MILLISECOND;
    private static final long UNIX_EPOCH_IN_NTFS_UNITS = -FileTimes.UNIX_TO_NTFS_OFFSET;

    public static Stream<Arguments> fileTimeNanoUnitsToNtfsProvider() {
        return Stream.of(
                Arguments.of("1601-01-01T00:00:00.0000000Z", 0),
                Arguments.of("1601-01-01T00:00:00.0000001Z", 1),
                Arguments.of("1601-01-01T00:00:00.0000010Z", 10),
                Arguments.of("1601-01-01T00:00:00.0000100Z", 100),
                Arguments.of("1601-01-01T00:00:00.0001000Z", 1000),
                Arguments.of("1600-12-31T23:59:59.9999999Z", -1),

                Arguments.of("+30828-09-14T02:48:05.477580700Z", Long.MAX_VALUE),
                Arguments.of("+30828-09-14T02:48:05.477580600Z", Long.MAX_VALUE - 1),
                Arguments.of("+30828-09-14T02:48:05.477579700Z", Long.MAX_VALUE - 10),
                Arguments.of("+30828-09-14T02:48:05.477570700Z", Long.MAX_VALUE - 100),
                Arguments.of("+30828-09-14T02:48:05.477480700Z", Long.MAX_VALUE - 1000),

                Arguments.of("-27627-04-19T21:11:54.522419200Z", Long.MIN_VALUE),
                Arguments.of("-27627-04-19T21:11:54.522419300Z", Long.MIN_VALUE + 1),
                Arguments.of("-27627-04-19T21:11:54.522420200Z", Long.MIN_VALUE + 10),
                Arguments.of("-27627-04-19T21:11:54.522429200Z", Long.MIN_VALUE + 100),
                Arguments.of("-27627-04-19T21:11:54.522519200Z", Long.MIN_VALUE + 1000),

                Arguments.of("1601-01-01T00:00:00.0010000Z", ONE_MILLISECOND_IN_NTFS_UNITS),
                Arguments.of("1601-01-01T00:00:00.0010001Z", ONE_MILLISECOND_IN_NTFS_UNITS + 1),
                Arguments.of("1601-01-01T00:00:00.0009999Z", ONE_MILLISECOND_IN_NTFS_UNITS - 1),
                Arguments.of("1600-12-31T23:59:59.9990000Z", -ONE_MILLISECOND_IN_NTFS_UNITS),
                Arguments.of("1600-12-31T23:59:59.9990001Z", -ONE_MILLISECOND_IN_NTFS_UNITS + 1),
                Arguments.of("1600-12-31T23:59:59.9989999Z", -ONE_MILLISECOND_IN_NTFS_UNITS - 1),

                Arguments.of("1970-01-01T00:00:00.0000000Z", UNIX_EPOCH_IN_NTFS_UNITS),
                Arguments.of("1970-01-01T00:00:00.0000001Z", UNIX_EPOCH_IN_NTFS_UNITS + 1),
                Arguments.of("1970-01-01T00:00:00.0010000Z", UNIX_EPOCH_IN_NTFS_UNITS + ONE_MILLISECOND_IN_NTFS_UNITS),
                Arguments.of("1969-12-31T23:59:59.9999999Z", UNIX_EPOCH_IN_NTFS_UNITS - 1),
                Arguments.of("1969-12-31T23:59:59.9990000Z", UNIX_EPOCH_IN_NTFS_UNITS - ONE_MILLISECOND_IN_NTFS_UNITS));
    }

    @ParameterizedTest
    @MethodSource("fileTimeNanoUnitsToNtfsProvider")
    void testMaxJavaTimeParam(final String expectedInstantText, final long javaTime) {
        final Instant javaInstant = Instant.ofEpochMilli(javaTime);
        assertEquals(javaTime, javaInstant.toEpochMilli());

        final long ntfsTime = FileTimes.toNtfsTime(javaTime);
        final Instant roundTripInstant = FileTimes.ntfsTimeToInstant(ntfsTime);

        if (ntfsTime == Long.MIN_VALUE || ntfsTime == Long.MAX_VALUE) {
            return;
        }
        assertEquals(javaTime, roundTripInstant.toEpochMilli());
    }
}
